<template><div class="page-shell"><header class="page-header"><p class="eyebrow">{{mode==='FLASHCARD'?'Review':'Focused practice'}}</p><h1>{{mode==='FLASHCARD'?'Flashcards':'Drills'}}</h1><p>Choose skills, start a session, and learn from every answer.</p></header><p v-if="error" class="error-state" role="alert">{{error}}</p><section v-if="!session&&!result" class="setup glass-card"><div class="form-field"><label>Number of questions<select v-model.number="count"><option v-for="n in [5,10,15,20]" :key="n">{{n}}</option></select></label></div><div class="skill-picker"><template v-for="course in courses" :key="course.id"><h2>Grade {{course.grade}}</h2><label v-for="skill in course.units.flatMap(u=>u.skills)" :key="skill.code" :class="{selected:selected.includes(skill.code)}"><input v-model="selected" type="checkbox" :value="skill.code"><span><b>{{skill.title}}</b><small>{{skill.masteryStatus.replace('_',' ')}}</small></span></label></template></div><button class="button primary" @click="start" :disabled="loading||!selected.length">{{loading?'Preparing…':'Start session'}}</button></section><section v-else-if="session" class="questions"><article v-for="(q,index) in session.questions" :key="q.id" class="glass-card question"><p class="eyebrow">{{q.skillTitle}} · {{index+1}}/{{session.questions.length}}</p><h2>{{q.prompt}}</h2><template v-if="mode==='FLASHCARD'"><details><summary class="button secondary">Reveal answer</summary><strong class="solution">{{q.solution}}</strong><p>{{q.explanation}}</p></details><div class="answer-actions"><button class="button secondary" @click="answers[q.id]=''">Review again</button><button class="button primary" @click="answers[q.id]=q.solution">Got it</button></div></template><div v-else class="options"><label v-for="answer in q.answers" :key="answer" :class="{chosen:answers[q.id]===answer}"><input v-model="answers[q.id]" type="radio" :name="`q${q.id}`" :value="answer"><span>{{answer}}</span></label><details><summary>Need a hint?</summary><p>{{q.hint}}</p></details></div></article><button class="button primary submit" @click="complete">Complete session</button></section><section v-else class="result glass-card"><p class="eyebrow">Session complete</p><h2>{{result.score}} / {{result.total}}</h2><p>You earned {{result.xpEarned}} mastery XP.</p><div v-for="item in result.feedback" :key="item.questionId" :class="['feedback',item.correct?'correct':'incorrect']"><b>{{item.correct?'Correct':'Keep practicing'}} · {{item.prompt}}</b><p>Your answer: {{item.selectedAnswer||'Not answered'}} · Answer: {{item.correctAnswer}}</p><small>{{item.explanation}}</small></div><button class="button primary" @click="reset">Start another session</button></section></div></template>
<script>import{api}from'../api';export default{name:'Practice',props:{mode:{type:String,default:'DRILL'}},data:()=>({courses:[],selected:[],count:5,session:null,result:null,answers:{},loading:false,error:''}),async created(){document.title=`${this.mode==='FLASHCARD'?'Flashcards':'Drills'} · Math Practice`;try{this.courses=await api('/api/courses');if(this.$route.query.skill)this.selected=[this.$route.query.skill]}catch(e){this.error=e.message}},methods:{async start(){this.error='';this.loading=true;try{this.session=await api('/api/practice/sessions',{method:'POST',body:JSON.stringify({skillCodes:this.selected,mode:this.mode,questionCount:this.count})})}catch(e){this.error=e.message}finally{this.loading=false}},async complete(){try{this.result=await api(`/api/practice/sessions/${this.session.id}/complete`,{method:'POST',body:JSON.stringify({answers:Object.entries(this.answers).map(([questionId,answer])=>({questionId:Number(questionId),answer}))})});this.session=null;scrollTo({top:0,behavior:'smooth'})}catch(e){this.error=e.message}},reset(){this.session=null;this.result=null;this.answers={};this.error=''}}}</script>
<style scoped>.setup{padding:1.5rem;margin-bottom:4rem}.setup>.form-field{max-width:14rem}.skill-picker{display:grid;grid-template-columns:repeat(3,1fr);gap:.7rem;margin:1.5rem 0}.skill-picker h2{grid-column:1/-1;font:700 1.4rem var(--ff-serif);margin-top:1rem}.skill-picker label{padding:1rem;border:1px solid hsl(var(--clr-white-200)/.12);border-radius:1rem;cursor:pointer}.skill-picker label.selected{background:hsl(var(--clr-primary-400)/.25);border-color:hsl(var(--clr-accent-200)/.5)}.skill-picker input{position:absolute;opacity:0}.skill-picker span{display:grid}.skill-picker small{color:hsl(var(--clr-white-600));text-transform:lowercase}.questions{display:grid;gap:1rem;padding-bottom:4rem}.question{padding:1.5rem}.question h2{font:700 2rem var(--ff-serif);margin:.75rem 0 1.25rem}.options{display:grid;grid-template-columns:1fr 1fr;gap:.75rem}.options label{padding:1rem;border:1px solid hsl(var(--clr-white-200)/.14);border-radius:1rem;cursor:pointer}.options label.chosen{background:hsl(var(--clr-primary-400)/.3);border-color:hsl(var(--clr-accent-200))}.options details{grid-column:1/-1}.solution{display:block;font:800 3rem var(--ff-serif);color:hsl(var(--clr-accent-200));margin:1rem 0}.answer-actions{display:flex;gap:.75rem;margin-top:1rem}.submit{justify-self:start}.result{padding:2rem;margin-bottom:4rem}.result>h2{font:800 4rem var(--ff-serif);color:hsl(var(--clr-accent-200))}.feedback{padding:1rem;margin:1rem 0;border-left:4px solid}.feedback.correct{border-color:hsl(var(--clr-accent-400));background:hsl(var(--clr-accent-400)/.08)}.feedback.incorrect{border-color:hsl(5 65% 58%);background:hsl(5 65% 58%/.08)}.feedback small{color:hsl(var(--clr-white-600))}@media(max-width:45rem){.skill-picker{grid-template-columns:1fr}.options{grid-template-columns:1fr}}</style>
